import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, color, mix, smoothstep, fract, sin, dot, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, DoubleSide } = THREE;

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'home-headline';

  // ---- headline card plane: engineered gradient surface + subtle grain ----
  const cardW = 4.4;
  const cardH = 1.5;
  const cardGeo = new PlaneGeometry(cardW, cardH, 1, 1);
  const cardMat = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });

  const gradTop = color(palette.surface);
  const gradBottom = color(palette.ink);
  const t = uv().y;
  const grad = mix(gradBottom, gradTop, smoothstep(0.0, 1.0, t));

  // subtle grain via hash noise
  const grain = fract(
    sin(dot(uv(), vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grainTint = grain.sub(0.5).mul(0.035);

  cardMat.colorNode = grad.add(vec3(grainTint, grainTint, grainTint));
  cardMat.opacity = 0.0;

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, -0.02);
  root.add(cardMesh);

  // texture the card with the provided image, blended additively with the gradient
  let cardTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    cardTexture = tex;
    const texNode = texture(tex);
    cardMat.colorNode = mix(grad.add(vec3(grainTint, grainTint, grainTint)), texNode, 0.35);
    cardMat.needsUpdate = true;
  }).catch(() => {
    // asset unavailable — engineered gradient still carries the surface
  });

  // ---- headline text (verbatim copy from spec) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineText = items.length
    ? items.map((i) => i.text).join(' ')
    : 'A machined-metal watch atelier landing with catalog, pricing, jo';

  const textNode = ctx.fontAtlas.createText(headlineText, {
    fontSize: 31,
    color: palette.paper,
    align: 'left',
    maxWidthPx: 900,
    letterSpacingPx: 0.4,
  });
  textNode.position.set(-cardW / 2 + 0.3, 0, 0.02);
  textNode.userData.baseOpacity = 1;
  root.add(textNode);

  // ---- accent underline sliver, kept under 10% of frame, single accent use ----
  const accentGeo = new PlaneGeometry(1.1, 0.03, 1, 1);
  const accentMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  accentMat.colorNode = color(palette.accent);
  accentMat.opacity = 0.0;
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-cardW / 2 + 0.85, -cardH / 2 + 0.18, 0.03);
  root.add(accentMesh);

  // ---- apply configured cinematic primitives (none for this node, but honor contract) ----
  const primitiveHandles = [];
  const primitiveSpecs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveSpecs) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- weighted entrance: rise-in + settle, no linear easing ----
  const tl = gsap.timeline();
  root.position.y -= 0.3;
  tl.to(root.position, { y: root.position.y + 0.3, duration: 0.7, ease: 'power3.out' });
  tl.to(cardMat, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.05);
  tl.to(accentMat, { opacity: 0.9, duration: 0.5, ease: 'power2.out' }, 0.25);
  tl.fromTo(
    textNode.scale,
    { x: 0.98, y: 0.98, z: 0.98 },
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0.1
  );

  // idle breathing on the card (single slow transform, <=2%)
  const breathe = gsap.to(cardMesh.scale, {
    x: 1.015,
    y: 1.015,
    duration: 4.2,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    breathe.kill();
    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
      handle?.timeline?.kill?.();
    }
    cardGeo.dispose();
    cardMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    if (cardTexture?.dispose) cardTexture.dispose();
    if (textNode.userData?.cleanup) textNode.userData.cleanup();
  };

  return root;
}
